    FROM fin_star WHERE id IS NOT NULL
  )
  SELECT id, sum(106 * v / 255), sum(48 * v / 255), sum(64 * v / 255) FROM s GROUP BY id;

-- @excerpt FINALE
-- The wordmark: three letters that bounce off the floor line,
-- dy = int((sin(t*2.4 + i*0.75) - 1) * scale/6). Its outline (four 1-pixel
-- shifts, dark), then the chrome gradient over it, every fourth row darker.
DELETE FROM fin_logo;
INSERT INTO fin_logo
  WITH
  letter AS MATERIALIZED (
    SELECT k.n AS k, substr(lang, k.n + 1, 1) AS ch, logox + k.n * 6 * scale AS x, logoy, scale, w, h,
           CAST((sin(:n / 60.0 * 2.4 + k.n * 0.75) - 1) * scale / 6 AS INTEGER) AS dy
    FROM fin_lay, nums k WHERE k.n < length(lang)
  ),
  dots AS MATERIALIZED (
    SELECT letter.*, f.row, f.col FROM letter JOIN font f ON f.ch = letter.ch
  ),
  outline AS (
    SELECT 1 AS layer, (logoy + dots.dy + o.oy + row * scale + sy.n) * w + x + o.ox + col * scale + sx.n AS id,
           '180A20FF' AS hex
    FROM dots
    CROSS JOIN (SELECT -1 AS ox, 0 AS oy UNION ALL SELECT 1, 0 UNION ALL SELECT 0, -1 UNION ALL SELECT 0, 1) o
    JOIN nums sy ON sy.n < scale JOIN nums sx ON sx.n < scale
    WHERE x + o.ox + col * scale + sx.n BETWEEN 0 AND w - 1
      AND logoy + dots.dy + o.oy + row * scale + sy.n BETWEEN 0 AND h - 1
  ),
  -- the gradient: cream to rose to violet down the glyph height
  grad0 AS (
    SELECT x + col * scale + sx.n AS xx, logoy + dy + row * scale + sy.n AS yy, logoy, scale, w
    FROM dots JOIN nums sy ON sy.n < scale JOIN nums sx ON sx.n < scale
    WHERE x + col * scale + sx.n BETWEEN 0 AND w - 1 AND logoy + dy + row * scale + sy.n BETWEEN 0 AND h - 1
  ),
  grad1 AS (SELECT *, max(0.0, min(1.0, (CAST(yy - logoy AS REAL) / (7 * scale)) * 536870913.0 - ((CAST(yy - logoy AS REAL) / (7 * scale)) * 536870913.0 - (CAST(yy - logoy AS REAL) / (7 * scale))))) AS f FROM grad0),
  grad2 AS (
    SELECT xx, yy, w, f < 0.5 AS top, iif(f < 0.5, f * 2, (f - 0.5) * 2) AS u FROM grad1
  ),
  grad3 AS (
    SELECT xx, yy, w,
      CAST(iif(top, (232 + ((23 * u) * 536870913.0 - ((23 * u) * 536870913.0 - (23 * u)))) * 536870913.0 - ((232 + ((23 * u) * 536870913.0 - ((23 * u) * 536870913.0 - (23 * u)))) * 536870913.0 - (232 + ((23 * u) * 536870913.0 - ((23 * u) * 536870913.0 - (23 * u))))),  (255 + ((-127 * u) * 536870913.0 - ((-127 * u) * 536870913.0 - (-127 * u)))) * 536870913.0 - ((255 + ((-127 * u) * 536870913.0 - ((-127 * u) * 536870913.0 - (-127 * u)))) * 536870913.0 - (255 + ((-127 * u) * 536870913.0 - ((-127 * u) * 536870913.0 - (-127 * u)))))) AS INTEGER) AS r,
      CAST(iif(top, (246 + ((-90 * u) * 536870913.0 - ((-90 * u) * 536870913.0 - (-90 * u)))) * 536870913.0 - ((246 + ((-90 * u) * 536870913.0 - ((-90 * u) * 536870913.0 - (-90 * u)))) * 536870913.0 - (246 + ((-90 * u) * 536870913.0 - ((-90 * u) * 536870913.0 - (-90 * u))))), (156 + ((-124 * u) * 536870913.0 - ((-124 * u) * 536870913.0 - (-124 * u)))) * 536870913.0 - ((156 + ((-124 * u) * 536870913.0 - ((-124 * u) * 536870913.0 - (-124 * u)))) * 536870913.0 - (156 + ((-124 * u) * 536870913.0 - ((-124 * u) * 536870913.0 - (-124 * u)))))) AS INTEGER) AS g,
      CAST(iif(top, (255 + ((-131 * u) * 536870913.0 - ((-131 * u) * 536870913.0 - (-131 * u)))) * 536870913.0 - ((255 + ((-131 * u) * 536870913.0 - ((-131 * u) * 536870913.0 - (-131 * u)))) * 536870913.0 - (255 + ((-131 * u) * 536870913.0 - ((-131 * u) * 536870913.0 - (-131 * u))))), (124 + ((-36 * u) * 536870913.0 - ((-36 * u) * 536870913.0 - (-36 * u)))) * 536870913.0 - ((124 + ((-36 * u) * 536870913.0 - ((-36 * u) * 536870913.0 - (-36 * u)))) * 536870913.0 - (124 + ((-36 * u) * 536870913.0 - ((-36 * u) * 536870913.0 - (-36 * u)))))) AS INTEGER) AS b
    FROM grad2
  ),
  grad AS (
    SELECT 2 AS layer, yy * w + xx AS id,
           iif(yy & 3 = 0, printf('%02X%02X%02XFF', r * 3 / 4, g * 3 / 4, b * 3 / 4), printf('%02X%02X%02XFF', r, g, b)) AS hex
    FROM grad3
  )
  SELECT id, hex FROM (SELECT id, max(layer), hex FROM (SELECT * FROM outline UNION ALL SELECT * FROM grad) GROUP BY id);

-- The reflection, under the letters' light: mirrored about the floor line,
-- fading over reflH rows (a = (1-d)^2, intensity 125*a), its colour from
-- cream to violet, added to what is there.
DELETE FROM fin_refl;
INSERT INTO fin_refl
  WITH
  letter AS MATERIALIZED (
    SELECT substr(lang, k.n + 1, 1) AS ch, logox + k.n * 6 * scale AS x, floory, reflh, scale, w, h,
           CAST((sin(:n / 60.0 * 2.4 + k.n * 0.75) - 1) * scale / 6 AS INTEGER) AS dy
    FROM fin_lay, nums k WHERE k.n < length(lang)
  ),
  px AS (
    SELECT x + f.col * scale + sx.n AS xx, floory + (6 - f.row) * scale - dy + sy.n AS yy, floory, reflh, w
    FROM letter JOIN font f ON f.ch = letter.ch JOIN nums sy ON sy.n < scale JOIN nums sx ON sx.n < scale
    WHERE x + f.col * scale + sx.n BETWEEN 0 AND w - 1 AND floory + (6 - f.row) * scale - dy + sy.n BETWEEN 0 AND h - 1
  ),
  d AS (SELECT xx, yy, w, (CAST(yy - floory AS REAL) / reflh) * 536870913.0 - ((CAST(yy - floory AS REAL) / reflh) * 536870913.0 - (CAST(yy - floory AS REAL) / reflh)) AS d FROM px),
  a AS (SELECT xx, yy, w, d, (((1 - d) * 536870913.0 - ((1 - d) * 536870913.0 - (1 - d))) * ((1 - d) * 536870913.0 - ((1 - d) * 536870913.0 - (1 - d)))) * 536870913.0 - ((((1 - d) * 536870913.0 - ((1 - d) * 536870913.0 - (1 - d))) * ((1 - d) * 536870913.0 - ((1 - d) * 536870913.0 - (1 - d)))) * 536870913.0 - (((1 - d) * 536870913.0 - ((1 - d) * 536870913.0 - (1 - d))) * ((1 - d) * 536870913.0 - ((1 - d) * 536870913.0 - (1 - d))))) AS a FROM d WHERE d <= 1),
  c AS (
    SELECT yy * w + xx AS id, CAST((125 * a) * 536870913.0 - ((125 * a) * 536870913.0 - (125 * a)) AS INTEGER) AS v,
           CAST((232 + ((-104 * d) * 536870913.0 - ((-104 * d) * 536870913.0 - (-104 * d)))) * 536870913.0 - ((232 + ((-104 * d) * 536870913.0 - ((-104 * d) * 536870913.0 - (-104 * d)))) * 536870913.0 - (232 + ((-104 * d) * 536870913.0 - ((-104 * d) * 536870913.0 - (-104 * d))))) AS INTEGER) AS r, CAST((246 + ((-214 * d) * 536870913.0 - ((-214 * d) * 536870913.0 - (-214 * d)))) * 536870913.0 - ((246 + ((-214 * d) * 536870913.0 - ((-214 * d) * 536870913.0 - (-214 * d)))) * 536870913.0 - (246 + ((-214 * d) * 536870913.0 - ((-214 * d) * 536870913.0 - (-214 * d))))) AS INTEGER) AS g,
           CAST((255 + ((-167 * d) * 536870913.0 - ((-167 * d) * 536870913.0 - (-167 * d)))) * 536870913.0 - ((255 + ((-167 * d) * 536870913.0 - ((-167 * d) * 536870913.0 - (-167 * d)))) * 536870913.0 - (255 + ((-167 * d) * 536870913.0 - ((-167 * d) * 536870913.0 - (-167 * d))))) AS INTEGER) AS b
    FROM a
  )
  SELECT id, r * v / 255, g * v / 255, b * v / 255 FROM c WHERE v > 0;
-- @end

-- Every pixel: background, + glow + stars (saturating), then the floor
-- line in float32, + the reflection, and the topmost text if any.
WITH
q1 AS (
  SELECT p.*, (dx2 + dy2) * 536870913.0 - ((dx2 + dy2) * 536870913.0 - (dx2 + dy2)) AS d2, pulse FROM fin_t CROSS JOIN fin_px p LIMIT -1
),
q2 AS (
  SELECT q1.*, iif(d2 < 1, (1 - d2) * 536870913.0 - ((1 - d2) * 536870913.0 - (1 - d2)), NULL) AS g1 FROM q1 LIMIT -1
),
q3 AS (
  SELECT q2.*, (g1 * ((g1 * pulse) * 536870913.0 - ((g1 * pulse) * 536870913.0 - (g1 * pulse)))) * 536870913.0 - ((g1 * ((g1 * pulse) * 536870913.0 - ((g1 * pulse) * 536870913.0 - (g1 * pulse)))) * 536870913.0 - (g1 * ((g1 * pulse) * 536870913.0 - ((g1 * pulse) * 536870913.0 - (g1 * pulse))))) AS gl FROM q2 LIMIT -1
),
q4 AS (
  SELECT q3.id, q3.hex, fr, fg, fb,
    min(255, q3.r + coalesce(CAST((gl * 120) * 536870913.0 - ((gl * 120) * 536870913.0 - (gl * 120)) AS INTEGER), 0) + coalesce(a.r, 0)) AS r,
    min(255, q3.g + coalesce(CAST((gl * 22) * 536870913.0 - ((gl * 22) * 536870913.0 - (gl * 22)) AS INTEGER), 0) + coalesce(a.g, 0)) AS g,
    min(255, q3.b + coalesce(CAST((gl * 100) * 536870913.0 - ((gl * 100) * 536870913.0 - (gl * 100)) AS INTEGER), 0) + coalesce(a.b, 0)) AS b
  FROM q3 LEFT JOIN fin_add a ON a.id = q3.id LIMIT -1
),
q5 AS (
  SELECT id, hex,
    iif(fr IS NULL, r, CAST(min(255.0, (r + fr) * 536870913.0 - ((r + fr) * 536870913.0 - (r + fr))) AS INTEGER)) AS r,
    iif(fr IS NULL, g, CAST(min(255.0, (g + fg) * 536870913.0 - ((g + fg) * 536870913.0 - (g + fg))) AS INTEGER)) AS g,
    iif(fr IS NULL, b, CAST(min(255.0, (b + fb) * 536870913.0 - ((b + fb) * 536870913.0 - (b + fb))) AS INTEGER)) AS b
  FROM q4 LIMIT -1
)
SELECT unhex(group_concat(coalesce(q5.hex, l.hex,
  printf('%02X%02X%02XFF', min(255, q5.r + coalesce(f.r, 0)), min(255, q5.g + coalesce(f.g, 0)),
         min(255, q5.b + coalesce(f.b, 0)))), ''))
FROM q5 LEFT JOIN fin_logo l ON l.id = q5.id LEFT JOIN fin_refl f ON f.id = q5.id;
